 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, color, mix, smoothstep, texture, uniform, fract, sin, dot, mul, add } from 'three/tsl';

function hexToBytes(hex) {
  const v = hex.replace('#', '');
  const bigint = parseInt(v, 16);
  return [
    (bigint >> 16) & 255,
    (bigint >> 8) & 255,
    bigint & 255,
    255
  ];
}

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, DataTexture, SRGBColorSpace } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = textItems.find((t) => t.role === 'headline') ?? textItems[0] ?? { text: 'Collection' };

  const atlas = config.atlasRegion ?? config.intent?.visualSpec?.atlasRegion ?? { x: 0, y: 0, width: 512, height: 320 };
  const rect = atlas.sourceRect ?? atlas;
  const cardAspect = rect.width / rect.height;

  const root = new Group();
  root.name = config.id ?? 'collection-title';

  const timelines = [];

  const grain = (coord) => {
    const p = mul(coord, 800);
    return fract(mul(sin(dot(p, vec2(12.9898, 78.233))), 43758.5453));
  };

  const gradient = mix(color(colors.surface), color(colors.ink), smoothstep(0, 1, uv().y));
  const noise = grain(uv()).mul(0.035);
  const backdropMat = new MeshBasicNodeMaterial({ colorNode: add(gradient, noise) });
  const backdropGeo = new PlaneGeometry(7.0, 6.0);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.5, -2.5);
  root.add(backdrop);

  const cardGroup = new Group();
  root.add(cardGroup);

  const placeholderBytes = new Uint8Array(hexToBytes(colors.surface));
  const placeholderTex = new DataTexture(placeholderBytes, 1, 1);
  placeholderTex.colorSpace = SRGBColorSpace;
  placeholderTex.needsUpdate = true;

  const texUniform = uniform(placeholderTex);
  const cardMat = new MeshBasicNodeMaterial({ colorNode: texture(texUniform, uv()) });
  const cardGeo = new PlaneGeometry(1, 1);
  const card = new Mesh(cardGeo, cardMat);
  const cardWidth = 3.8;
  const cardHeight = cardWidth / cardAspect;
  card.scale.set(cardWidth, cardHeight, 1);
  cardGroup.add(card);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((loadedTex) => {
      if (!loadedTex) return;
      loadedTex.colorSpace = SRGBColorSpace;
      texUniform.value = loadedTex;
      loadedTex.needsUpdate = true;
      cardMat.needsUpdate = true;
    });
  }

  const title = ctx.fontAtlas.createText(headline.text, {
    fontSize: headline.typography?.fontSize ?? 96,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 2
  });
  title.position.set(0, cardHeight * 0.5 + 0.45, 0.15);
  cardGroup.add(title);

  const accentMat = new MeshBasicNodeMaterial({ colorNode: color(colors.accent) });
  const accentGeo = new PlaneGeometry(1.1, 0.05);
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(0, title.position.y - 0.28, 0.18);
  cardGroup.add(accentBar);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl?.kill?.());
    placeholderTex.dispose();
    const liveTex = texUniform.value;
    if (liveTex && liveTex !== placeholderTex && liveTex.dispose) liveTex.dispose();
    cardMat.dispose();
    cardGeo.dispose();
    backdropMat.dispose();
    backdropGeo.dispose();
    accentMat.dispose();
    accentGeo.dispose();
  };

  return root;
}
